class Solution {
public:
    long long maxSpending(vector<vector<int>>& values) {
        vector<int> items;
        for (const auto& row : values) {
            items.insert(items.end(), row.begin(), row.end());
        }
        sort(items.begin(), items.end());
        long long ans = 0;
        for (long long d = 1; d <= items.size(); d++) {
            ans += items[d - 1] * d;
        }
        return ans;
    }
};

class Solution {
    public long maxSpending(int[][] values) {
        int m = values.length, n = values[0].length;
        int[] items = new int[m * n];
        int idx = 0;
        for (int[] row : values) {
            for (int v : row) items[idx++] = v;
        }
        Arrays.sort(items);
        long ans = 0;
        for (int i = 0; i < items.length; i++) {
            ans += (long) items[i] * (i + 1);
        }
        return ans;
    }
}

